    vCutsNew         *Vec_Ptr_t;         // new cuts by node ID
    vCutsOld         *Vec_Ptr_t;         // old cuts by node ID
    vCutsTemp         *Vec_Ptr_t;        // temp cuts for cutset nodes by cutset node number
    // memory management
    pMmCuts   *Extra_MmFixed_t;
    EntrySize                int32;
    nTruthWords                int32;
    // temporary variables
    pReady         *Cut_Cut_t;
    vTemp         *Vec_Ptr_t;
    fCompl0                int32;
    fCompl1                int32;
    fSimul                int32;
    nNodeCuts                int32;
    Cut_Cut_t *        pStore0[2];
    Cut_Cut_t *        pStore1[2];
    pCompareOld         *Cut_Cut_t;
    pCompareNew         *Cut_Cut_t;
    puTemp [4]*uint32;
    // record of the cut computation
    vNodeCuts         *Vec_Int_t;        // the number of cuts for each node
    vNodeStarts         *Vec_Int_t;      // the number of the starting cut of each node
    vCutPairs         *Vec_Int_t;        // the pairs of parent cuts for each cut
    // minimum delay mapping with the given cuts
    vCutsMax         *Vec_Ptr_t;
    vDelays         *Vec_Int_t;
    vDelays2         *Vec_Int_t;
    nDelayMin                int32;
    // statistics
    nCutsCur                int32;
    nCutsAlloc                int32;
    nCutsDealloc                int32;
    nCutsPeak                int32;
    nCutsTriv                int32;
    nCutsFilter                int32;
    nCutsLimit                int32;
    nNodes                int32;
    nNodesDag                int32;
    nNodesNoCuts                int32;
    // runtime
    timeMerge            abctime;
    timeUnion            abctime;
    timeTruth            abctime;
    timeFilter            abctime;
    timeHash            abctime;
    timeMap            abctime;
}

