// computes signature of the node
func Cut_NodeSign(Node int32) uint32 { return (1 << (Node % 31));                        }
func Cut_TruthWords(nVarsMax int32) int32 { if nVarsMax <= 5 {
    return 1;
} else {
    return (1 << (nVarsMax - 5));
} }

